const status = Number($json.statusCode) || 0;
    const parseJson = value => {
      if (value === undefined || value === null || value === '') return null;
      if (typeof value === 'object') return value;
      if (typeof value !== 'string') return null;
      try { return JSON.parse(value); } catch { return null; }
    };
    const failure = (reason, upstreamStatus = status) => ({
      json: {
        result: 'hubspot_failure',
        step: 'Find Awaiting SLA Deals',
        reason,
        retryable: !upstreamStatus || upstreamStatus === 429 || upstreamStatus >= 500,
        upstream_status: upstreamStatus || null
      }
    });
    if (status !== 200) {
      return [failure('HubSpot Deal search failed; no SLA records were changed.')];
    }
    const response = parseJson($json.body ?? $json.data);
    if (!response || !Array.isArray(response.results) || !Number.isInteger(Number(response.total))) {
      return [failure('HubSpot returned an unreadable Deal search response.')];
    }
    if (response.paging?.next?.after) {
      return [failure('More than 200 awaiting Deals matched. V1 stopped without writes; reduce the backlog or add reviewed pagination.', 422)];
    }
    if (Number(response.total) !== response.results.length) {
      return [failure('HubSpot Deal search response was internally inconsistent.')];
    }
    if (!response.results.length) {
      return [{ json: { result: 'no_awaiting_deals' } }];
    }
    const run_started_at = new Date().toISOString();
    return response.results.map(deal => ({
      json: {
        deal_id: String(deal?.id ?? deal?.properties?.hs_object_id ?? ''),
        deal_properties: deal?.properties ?? {},
        run_started_at
      }
    }));

const data = { ...$json };
    const properties = data.deal_properties ?? {};
    const errors = [];
    const dealId = String(data.deal_id ?? '').trim();
    const receivedRaw = properties.lead_received_at;
    const receivedMs = Date.parse(receivedRaw);
    const ownerId = String(properties.hubspot_owner_id ?? '').trim();
    if (!dealId) errors.push('Deal ID is missing.');
    if (!receivedRaw || !Number.isFinite(receivedMs)) errors.push('lead_received_at is missing or malformed.');
    if (!ownerId) errors.push('hubspot_owner_id is missing; assigned-salesperson activity cannot be qualified.');
    if (properties.lead_response_sla_status !== 'AWAITING_RESPONSE') errors.push('Deal is no longer AWAITING_RESPONSE.');
    if (properties.delivery_status !== 'DELIVERED') errors.push('Deal is not DELIVERED.');
    if (properties.first_human_response_at) errors.push('first_human_response_at is already populated while status is AWAITING_RESPONSE.');
    if (errors.length) {
      return {
        json: {
          result: 'manual_review_required',
          deal_id: dealId || undefined,
          reason: errors.join(' ')
        }
      };
    }
    data.deal_id = dealId;
    data.owner_id = ownerId;
    data.lead_received_at = new Date(receivedMs).toISOString();
    data.sla_deadline_at = new Date(receivedMs + 30 * 60 * 1000).toISOString();
    data.case_valid = true;
    delete data.deal_properties;
    return { json: data };

const result = { result: 'manual_review_required', reason: $json.reason || 'Deal state is invalid.' };
    if ($json.deal_id) result.deal_id = String($json.deal_id);
    return { json: result };

const data = { ...$('Validate SLA Case').item.json };
    const status = Number($json.statusCode) || 0;
    const parseJson = value => {
      if (value === undefined || value === null || value === '') return null;
      if (typeof value === 'object') return value;
      if (typeof value !== 'string') return null;
      try { return JSON.parse(value); } catch { return null; }
    };
    const fail = reason => ({
      ...data,
      result: 'hubspot_failure',
      step: 'Find Deal Emails',
      reason,
      retryable: !status || status === 429 || status >= 500,
      upstream_status: status || null
    });
    if (status !== 200) return { json: fail('HubSpot email search failed; Deal state was preserved.') };
    const response = parseJson($json.body ?? $json.data);
    if (!response || !Array.isArray(response.results)) return { json: fail('HubSpot returned an unreadable email search response.') };
    if (response.paging?.next?.after) return { json: fail('More than 200 Deal emails require review; no SLA update was made.') };
    data.email_activities = response.results;
    return { json: data };

const data = { ...$('Parse Email Search').item.json };
    const status = Number($json.statusCode) || 0;
    const parseJson = value => {
      if (value === undefined || value === null || value === '') return null;
      if (typeof value === 'object') return value;
      if (typeof value !== 'string') return null;
      try { return JSON.parse(value); } catch { return null; }
