      result: 'hubspot_failure',
      step: 'Find Deal Calls',
      reason,
      retryable: !status || status === 429 || status >= 500,
      upstream_status: status || null
    });
    if (status !== 200) return { json: fail('HubSpot call search failed; Deal state was preserved.') };
    const response = parseJson($json.body ?? $json.data);
    if (!response || !Array.isArray(response.results)) return { json: fail('HubSpot returned an unreadable call search response.') };
    if (response.paging?.next?.after) return { json: fail('More than 200 Deal calls require review; no SLA update was made.') };
