const data = { ...$('Parse Call Search').item.json };
    const status = Number($json.statusCode) || 0;
    const parseJson = value => {
      if (value === undefined || value === null || value === '') return null;
      if (typeof value === 'object') return value;
      if (typeof value !== 'string') return null;
      try { return JSON.parse(value); } catch { return null; }
    };
    const fail = reason => ({
      ...data,
      result: 'hubspot_failure',
      step: 'Find Deal Meetings',
      reason,
      retryable: !status || status === 429 || status >= 500,
      upstream_status: status || null
    });
    if (status !== 200) return { json: fail('HubSpot meeting search failed; Deal state was preserved.') };
    const response = parseJson($json.body ?? $json.data);
    if (!response || !Array.isArray(response.results)) return { json: fail('HubSpot returned an unreadable meeting search response.') };
    if (response.paging?.next?.after) return { json: fail('More than 200 Deal meetings require review; no SLA update was made.') };
    data.meeting_activities = response.results;
    return { json: data };

const data = { ...$json };
    const candidates = [];
    const receivedMs = Date.parse(data.lead_received_at);
    const normalize = (value, type, activityId) => {
      const ms = Date.parse(value);
      if (!Number.isFinite(ms) || ms < receivedMs) return;
      candidates.push({ type, activity_id: String(activityId), timestamp: new Date(ms).toISOString(), ms });
    };
    const explicitlyNonSentEmailStatuses = new Set(['BOUNCED', 'FAILED', 'SCHEDULED', 'SENDING']);
    for (const activity of data.email_activities ?? []) {
      const p = activity?.properties ?? {};
      const owned = String(p.hubspot_owner_id ?? '') === data.owner_id;
      const direction = String(p.hs_email_direction ?? '').trim().toUpperCase();
      const status = String(p.hs_email_status ?? '').trim().toUpperCase();
      if (owned && direction === 'EMAIL' && !explicitlyNonSentEmailStatuses.has(status)) {
        normalize(p.hs_timestamp, 'email', activity.id);
      }
    }
    for (const activity of data.call_activities ?? []) {
      const p = activity?.properties ?? {};
      const owned = String(p.hubspot_owner_id ?? '') === data.owner_id;
      if (owned && String(p.hs_call_status ?? '').toUpperCase() === 'COMPLETED') {
        normalize(p.hs_timestamp, 'call', activity.id);
      }
    }
    const explicitlyNonCompletedMeetingOutcomes = new Set(['CANCELED', 'CANCELLED', 'NO_SHOW', 'RESCHEDULED', 'SCHEDULED']);
    for (const activity of data.meeting_activities ?? []) {
      const p = activity?.properties ?? {};
      const owned = String(p.hubspot_owner_id ?? '') === data.owner_id;
      const outcome = String(p.hs_meeting_outcome ?? '').trim().toUpperCase().replace(/[\s-]+/g, '_');
      const meetingTimestamp = Number.isFinite(Date.parse(p.hs_meeting_start_time)) ? p.hs_meeting_start_time : p.hs_timestamp;
      if (owned && !explicitlyNonCompletedMeetingOutcomes.has(outcome)) {
        normalize(meetingTimestamp, 'meeting', activity.id);
      }
    }
    candidates.sort((a, b) => a.ms - b.ms || a.type.localeCompare(b.type) || a.activity_id.localeCompare(b.activity_id));
    const earliest = candidates[0];
    data.qualifying_response_count = candidates.length;
    data.first_human_response_at = earliest?.timestamp;
    data.first_response_type = earliest?.type;
    data.first_response_activity_id = earliest?.activity_id;
    delete data.email_activities;
    delete data.call_activities;
    delete data.meeting_activities;
    return { json: data };

const data = { ...$json };
    const deadlineMs = Date.parse(data.sla_deadline_at);
    const responseMs = data.first_human_response_at ? Date.parse(data.first_human_response_at) : null;
    const nowMs = Date.now();
    if (!Number.isFinite(deadlineMs) || (responseMs !== null && !Number.isFinite(responseMs))) {
      return { json: { result: 'manual_review_required', deal_id: data.deal_id, reason: 'SLA deadline or qualifying response timestamp is malformed.' } };
    }
    if (responseMs !== null) {
      if (responseMs <= deadlineMs) {
        data.result = 'responded_in_sla';
        data.lead_response_sla_status = 'RESPONDED_IN_SLA';
      } else {
        data.result = 'late_response';
        data.lead_response_sla_status = 'BREACHED';
      }
      data.update_properties = {
        first_human_response_at: data.first_human_response_at,
        lead_response_sla_status: data.lead_response_sla_status
      };
      data.requires_update = true;
      return { json: data };
    }
    if (nowMs > deadlineMs) {
      data.result = 'sla_breached';
      data.lead_response_sla_status = 'BREACHED';
      data.update_properties = { lead_response_sla_status: 'BREACHED' };
      data.requires_update = true;
      return { json: data };
    }
    data.result = 'sla_within_target';
    data.lead_response_sla_status = 'AWAITING_RESPONSE';
    data.requires_update = false;
    return { json: data };

const data = { ...$('Evaluate SLA').item.json };
    const status = Number($json.statusCode) || 0;
    const parseJson = value => {
      if (value === undefined || value === null || value === '') return null;
      if (typeof value === 'object') return value;
      if (typeof value !== 'string') return null;
      try { return JSON.parse(value); } catch { return null; }
    };
    const failure = reason => ({
      result: 'hubspot_failure',
      step: 'Update Deal SLA State',
      deal_id: data.deal_id,
      reason,
      retryable: !status || status === 429 || status >= 500,
      upstream_status: status || null
    });
    if (![200, 201, 204].includes(status)) {
      return { json: failure('HubSpot Deal update failed or was uncertain. Do not infer a new SLA state from this execution.') };
    }
    if (status !== 204) {
      const response = parseJson($json.body ?? $json.data);
      if (!response || String(response.id ?? '') !== data.deal_id || typeof response.properties !== 'object') {
        return { json: failure('HubSpot returned an unreadable or mismatched Deal update response.') };
      }
      const actualStatus = response.properties.lead_response_sla_status;
      if (actualStatus !== data.update_properties.lead_response_sla_status) {
        return { json: failure('HubSpot did not confirm the requested SLA status.') };
      }
      if (data.update_properties.first_human_response_at) {
        const expected = Date.parse(data.update_properties.first_human_response_at);
        const actual = Date.parse(response.properties.first_human_response_at);
        if (!Number.isFinite(actual) || actual !== expected) {
          return { json: failure('HubSpot did not confirm first_human_response_at.') };
        }
      }
    }
    data.update_confirmed = true;
    delete data.update_properties;
    return { json: data };

const allowed = ['result', 'deal_id', 'first_human_response_at', 'lead_response_sla_status'];
    const output = Object.fromEntries(allowed.filter(key => $json[key] !== undefined).map(key => [key, $json[key]]));
    return { json: output };

const allowed = ['result', 'step', 'deal_id', 'reason', 'retryable', 'upstream_status'];
    const output = Object.fromEntries(allowed.filter(key => $json[key] !== undefined).map(key => [key, $json[key]]));
    if (output.result !== 'hubspot_failure') {
      output.result = 'hubspot_failure';
      output.reason = output.reason || 'An unexpected HubSpot failure occurred.';
      output.retryable = false;
    }
    return { json: output };
